using System.Diagnostics;
using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using Microsoft.Win32;
namespace DDHI.Pharmacy.ServerManager;
public partial class MainWindow:Window {
 ServerProfile profile=ServerProfile.LoadOrDefault();ServerController controller=null!;bool busy;
 bool PreviewOnly=>File.Exists(Path.Combine(Directory.GetParent(profile.DataRoot)!.FullName,"preparation-only.flag"));
 readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(10)};
 public MainWindow(){InitializeComponent();MaxHeight=SystemParameters.WorkArea.Height;Height=Math.Min(Height,MaxHeight);WindowStartupLocation=WindowStartupLocation.CenterScreen;controller=new(profile,Log);Fill();timer.Tick+=async(s,e)=>{if(!busy&&profile.Prepared)await RefreshStatus();};timer.Start();}
 void Fill(){DataRootInput.Text=profile.DataRoot;PgBinInput.Text=profile.PostgresBin;PgPortInput.Text=profile.PostgresPort.ToString();ApiPortInput.Text=profile.ApiPort.ToString();HostnameInput.Text=profile.Hostname;PfxInput.Text=profile.CertificatePath;ApprovalInput.Text=profile.ApprovalReference;ModeInput.SelectedIndex=profile.Mode=="Local evaluation"?0:1;EndpointDisplay.Text=profile.Endpoint;DataDisplay.Text=profile.DataRoot;CertificatePathDisplay.Text=profile.CertificatePath;ThumbprintDisplay.Text=profile.CertificateThumbprint;CertificateNote.Text=profile.Mode=="Local evaluation"?"Local evaluation: localhost only. Health checks pin this exact certificate. Windows/workstation trust and hospital hostname approval have not been installed.":"Hospital LAN: approved hostname and an existing trusted PFX are required.";TlsStatus.Text=profile.Prepared?(profile.Mode=="Local evaluation"?"Local PFX · IT trust pending":"Hospital PFX supplied"):"Not configured";PrepareButton.IsEnabled=!profile.Prepared&&!busy&&!PreviewOnly;StartButton.IsEnabled=profile.Prepared&&!busy&&!PreviewOnly;StopButton.IsEnabled=profile.Prepared&&!busy&&!PreviewOnly;if(PreviewOnly)Banner.Text="Installer preview on this computer. Run the installer on the destination server to initialize PostgreSQL and the database.";}
 void ReadInputs(){if(profile.Prepared)return;profile.DataRoot=DataRootInput.Text.Trim();profile.PostgresBin=PgBinInput.Text.Trim();profile.PostgresPort=int.Parse(PgPortInput.Text);profile.ApiPort=int.Parse(ApiPortInput.Text);profile.Hostname=HostnameInput.Text.Trim().ToLowerInvariant();profile.CertificatePath=PfxInput.Text.Trim();profile.ApprovalReference=ApprovalInput.Text.Trim();profile.Mode=((ComboBoxItem)ModeInput.SelectedItem).Content.ToString()!;controller=new(profile,Log);}
 void Log(string text)=>Dispatcher.Invoke(()=>{Activity.AppendText($"{DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(8)):yyyy-MM-dd HH:mm:ss} {text}\n");Activity.ScrollToEnd();Banner.Text=text;});
 async Task Guard(Func<Task> action){if(busy)return;busy=true;Fill();try{await action();}catch(Exception ex){Log("Action could not complete: "+ex.Message);}finally{busy=false;Fill();}}
 async Task RefreshStatus(){if(!profile.Prepared){ApiStatus.Text="Not configured";DatabaseStatus.Text="Not configured";return;}try{DatabaseStatus.Text=await controller.VerifyDatabase();}catch(Exception ex){DatabaseStatus.Text="Unavailable";Banner.Text=ex.Message;}try{ApiStatus.Text=await controller.Health();}catch{ApiStatus.Text="Stopped / not ready";}}

 async void LoadedWindow(object sender,RoutedEventArgs e){if(PreviewOnly){await File.WriteAllTextAsync(Path.Combine(profile.ServerRoot,"Manager","preview-status.json"),JsonSerializer.Serialize(new{Machine=Environment.MachineName,DesktopWindowLoaded=true,PreparationOnly=true,LocalInitializationDisabled=true}));return;}if(profile.Prepared)await RefreshStatus();}

 async Task SaveProvisionReport(){string health;try{health=await controller.Health();}catch{health="Database prepared; API not started. Create the first administrator, then click Start server.";}var report=JsonSerializer.Serialize(new{Machine=Environment.MachineName,Database="ddhi_pharmacy",MigrationAccount="ddhi_migration",RuntimeAccount="ddhi_runtime",Hostname=profile.Hostname,HospitalHostnameApproved=profile.Mode!="Local evaluation",PfxPath=profile.CertificatePath,WindowsTrustInstalled=controller.LocalCertificateTrusted(),Mode=profile.Mode,Endpoint=profile.Endpoint,Status=health,DatabaseCheck=await controller.VerifyDatabase()},new JsonSerializerOptions{WriteIndented=true});await File.WriteAllTextAsync(Path.Combine(profile.DataRoot,"provision-status.json"),report);}
 async void PrepareServer(object sender,RoutedEventArgs e){try{ReadInputs();}catch(Exception ex){Log(ex.Message);return;}if(MessageBox.Show(this,"Create this independent server instance with the displayed paths and ports? Existing prepared database contents will not be replaced.","Confirm setup",MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;var password=PfxPassword.Password;PfxPassword.Clear();await Guard(async()=>{await controller.Prepare(password);if(UseWindowsServices.IsChecked==true)await controller.InstallWindowsServices();await RefreshStatus();Log("Database and certificate are ready. Create the first administrator, then click Start server.");await SaveProvisionReport();});}
 async void ConfigureServices(object sender,RoutedEventArgs e){if(PreviewOnly)return;if(MessageBox.Show(this,"Configure the three DDHI Windows services for this instance? Existing owned server processes will be stopped during configuration.","Configure Windows services",MessageBoxButton.OKCancel,MessageBoxImage.Question)==MessageBoxResult.OK)await Guard(async()=>{await controller.InstallWindowsServices();await RefreshStatus();});}
 void TrustLocalCertificate(object sender,RoutedEventArgs e){if(PreviewOnly)return;if(MessageBox.Show(this,"Trust this generated localhost certificate in the current Windows account's Trusted Root store? This does not establish hospital or workstation trust. Verify the displayed fingerprint first.","Authorize local certificate trust",MessageBoxButton.OKCancel,MessageBoxImage.Warning)!=MessageBoxResult.OK)return;try{controller.TrustLocalCertificateForCurrentUser();TlsStatus.Text="Trusted locally (this Windows account)";}catch(Exception ex){Log(ex.Message);}}
 async void StartServer(object sender,RoutedEventArgs e)=>await Guard(async()=>{await controller.Start();await RefreshStatus();});
 async void StopServer(object sender,RoutedEventArgs e){if(MessageBox.Show(this,"Stop this server and disconnect active clients? Confirm an approved downtime window before stopping a hospital server.","Stop server",MessageBoxButton.OKCancel,MessageBoxImage.Warning)==MessageBoxResult.OK)await Guard(async()=>{await controller.Stop();await RefreshStatus();});}
 async void CheckHealth(object sender,RoutedEventArgs e)=>await Guard(RefreshStatus);
 async void CreateAdmin(object sender,RoutedEventArgs e){var email=AdminEmail.Text.Trim();var password=AdminPassword.Password;if(string.IsNullOrWhiteSpace(email)||password.Length<12){Log("Enter an individual administrator email and a strong password of at least 12 characters.");return;}AdminPassword.Clear();await Guard(()=>controller.Bootstrap(email,password));}
 void BrowsePfx(object sender,RoutedEventArgs e){var dialog=new OpenFileDialog{Filter="PFX certificate|*.pfx;*.p12"};if(dialog.ShowDialog()==true)PfxInput.Text=dialog.FileName;}
 void OpenLogs(object sender,RoutedEventArgs e){var path=Path.Combine(profile.DataRoot,"logs");if(Directory.Exists(path))Process.Start(new ProcessStartInfo("explorer.exe"){Arguments="\""+path+"\"",UseShellExecute=true});}
 void OpenCertificate(object sender,RoutedEventArgs e){var path=Path.Combine(profile.DataRoot,"localhost-server.cer");if(File.Exists(path))Process.Start(new ProcessStartInfo(path){UseShellExecute=true});else Log("No local public certificate exists. Supply a hospital-issued PFX for LAN mode.");}
}
